// Staggered Dot Matrix Component
const DotMatrix: React.FC<{
  rows: number;
  cols: number;
  dotSize: number;
  spacing: number;
  color: string;
  delay: number;
}> = ({ rows, cols, dotSize, spacing, color, delay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: `repeat(${cols}, ${dotSize}px)`,
        gap: `${spacing}px`,
        transition: "none",
      }}
    >
      {Array.from({ length: rows * cols }).map((_, i) => {
        const rowIdx = Math.floor(i / cols);
        const colIdx = i % cols;
        const dotSpring = spring({
          frame,
          fps,
          config: { damping: 14, mass: 0.6 },
          delay: delay + (rowIdx + colIdx) * 1.5,
        });

        return (
          <div
            key={i}
            style={{
              width: dotSize,
              height: dotSize,
              borderRadius: "50%",
              backgroundColor: color,
              opacity: dotSpring,
              transform: `scale(${dotSpring})`,
              transition: "none",
            }}
          />
        );
      })}
    </div>
  );
};

